commands:
# Get all PCI-based Network Adapters
 $netAdapters = Get-CimInstance Win32_NetworkAdapter | Where-Object { $_.PNPDeviceID -like "PCI\VEN_*" } | Select-Object -ExpandProperty PNPDeviceID

 foreach ($net in $netAdapters) {
  $msiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$net\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
  if (Test-Path $msiKey) {
  Set-ItemProperty -Path $msiKey -Name "MSISupported" -Value 1
  }

  $affinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$net\Device Parameters\Interrupt Management\Affinity Policy"
  if (Test-Path $affinityKey) {
  Set-ItemProperty -Path $affinityKey -Name "DevicePriority" -Value 0
  }
 }

